program='''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    a = [row[:] for row in grid]
    comp_id = [[-1] * w for _ in range(h)]
    comp_sizes = {}
    comp_colors = {}
    cid = 0
    for r in range(h):
        for c in range(w):
            if comp_id[r][c] >= 0:
                continue
            color = a[r][c]
            q = [(r, c)]
            comp_id[r][c] = cid
            cells = []
            for y, x in q:
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and comp_id[ny][nx] < 0 and a[ny][nx] == color:
                        comp_id[ny][nx] = cid
                        q.append((ny, nx))
            comp_sizes[cid] = len(cells)
            comp_colors[cid] = color
            cid += 1
    for r in range(h):
        for c in range(w):
            k = comp_id[r][c]
            if comp_sizes[k] != 1:
                continue
            candidates = []
            best = h + w + 1
            for y in range(h):
                for x in range(w):
                    j = comp_id[y][x]
                    if comp_sizes[j] <= 1:
                        continue
                    d = abs(y-r) + abs(x-c)
