            tied = [color for color, n in counts.items() if n == max_count]
            if len(tied) > 1:
                # In a tie, prefer the nearby non-background object component.
                tied.sort(key=lambda color: min(comp_sizes[j] for j in candidates if comp_colors[j] == color))
            a[r][c] = tied[0]
    return a
